DROP TABLE IF EXISTS `dim_medecin`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `dim_medecin`  AS SELECT `m`.`id` AS `medecin_key`, `m`.`id` AS `medecin_id`, concat(`u`.`prenom`,' ',`u`.`nom`) AS `nom_complet`, `u`.`ville` AS `ville`, `u`.`gouvernorat` AS `gouvernorat` FROM (`medecin` `m` join `utilisateur` `u` on(`m`.`utilisateur_id` = `u`.`id`)) ;

-- --------------------------------------------------------

--
-- Structure de la vue `dim_patient`
--
DROP TABLE IF EXISTS `dim_patient`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `dim_patient`  AS SELECT `p`.`id` AS `patient_key`, `p`.`id` AS `patient_id`, concat(`u`.`prenom`,' ',`u`.`nom`) AS `nom_complet`, `u`.`ville` AS `ville`, `u`.`gouvernorat` AS `gouvernorat` FROM (`patient` `p` join `utilisateur` `u` on(`p`.`utilisateur_id` = `u`.`id`)) ;

-- --------------------------------------------------------

--
-- Structure de la vue `dim_specialite`
--
DROP TABLE IF EXISTS `dim_specialite`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `dim_specialite`  AS SELECT `specialite`.`id` AS `specialite_key`, `specialite`.`id` AS `specialite_id`, `specialite`.`nom` AS `nom_specialite` FROM `specialite` ;

