CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `fact_rendez_vous`  AS SELECT `rv`.`id` AS `id_fact`, `rv`.`medecin_id` AS `medecin_key`, `rv`.`patient_id` AS `patient_key`, `m`.`specialite_id` AS `specialite_key`, `rv`.`date_rendez_vous` AS `date_complete`, year(`rv`.`date_rendez_vous`) AS `annee`, month(`rv`.`date_rendez_vous`) AS `mois`, `rv`.`statut` AS `statut`, `rv`.`prix_consultation` AS `prix_consultation`, 1 AS `nb_rendez_vous` FROM (`rendez_vous` `rv` join `medecin` `m` on(`rv`.`medecin_id` = `m`.`id`)) ;

